#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_update_non_head_all_fields_non_zero(void) {
    // Setup: Build a linked list with at least two nodes.
    // We will update the second node (non-head) with all non-zero ct, wt, tat.
    int ids[] = {1, 2, 3};
    int ats[] = {0, 1, 2};
    int bts[] = {5, 4, 3};
    int priorities[] = {1, 2, 3};
    int size = 3;
    node *root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    // Verify initial CT, WT, TAT are zero (as set by insert).
    node *ptr = root;
    while (ptr != NULL && ptr->ID != 2) {
        ptr = ptr->next;
    }
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    // Test: Update node with ID 2 (non-head) with all non-zero values.
    int new_ct = 10;
    int new_wt = 5;
    int new_tat = 15;
    update(&root, 2, new_ct, new_wt, new_tat);

    // Assertions: Verify the second node's fields are updated.
    ptr = root;
    while (ptr != NULL && ptr->ID != 2) {
        ptr = ptr->next;
    }
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(new_ct, ptr->CT);
    TEST_ASSERT_EQUAL_INT(new_wt, ptr->WT);
    TEST_ASSERT_EQUAL_INT(new_tat, ptr->TAT);

    // Verify other nodes are unchanged.
    ptr = root;
    TEST_ASSERT_EQUAL_INT(1, ptr->ID);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);
    ptr = ptr->next->next; // node ID 3
    TEST_ASSERT_EQUAL_INT(3, ptr->ID);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    // Cleanup
    helper_cleanup_process_queue(&root);
    TEST_ASSERT_NULL(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_update_non_head_all_fields_non_zero);
    return UNITY_END();
}

